package com.hms.ui;
import com.hms.model.Doctor; import com.hms.service.DoctorService; import com.hms.util.UiUtil; import javax.swing.*; import javax.swing.table.DefaultTableModel; import java.awt.*; import java.util.*; import java.util.List;
public class DoctorPanel extends JPanel {private final DoctorService service;private final JTextField search=new JTextField();private final DefaultTableModel model=new DefaultTableModel(new String[]{"ID","Code","Doctor","Specialization","Department","Phone","Days","Hours"},0);public DoctorPanel(DoctorService s){service=s;setLayout(new BorderLayout(8,8));JPanel top=new JPanel(new BorderLayout(5,5));top.add(new JLabel("Search doctor/specialization/department:"),BorderLayout.WEST);top.add(search);JButton b=new JButton("Refresh");b.addActionListener(e->load());top.add(b,BorderLayout.EAST);add(top,BorderLayout.NORTH);add(new JScrollPane(new JTable(model)),BorderLayout.CENTER);search.addActionListener(e->load());load();}private void load(){try{model.setRowCount(0);for(Doctor d:service.findAll(search.getText()))model.addRow(new Object[]{d.doctorId(),d.doctorCode(),d.fullName(),d.specialization(),d.department(),d.phone(),d.availableDays(),d.availableFrom()+" - "+d.availableTo()});}catch(Exception e){UiUtil.showError(this,e);}}}
